package com.bananalab.lite;
import org.json.*;
public final class Stage51ReplacementCheck{
 static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 public static float jump(float t){return -96*t*(1-t);}public static float sway(float t){return (float)(24*Math.sin(t*Math.PI*2));}public static String reply(String s){return s.equals("taller banana")?"Motor nuevo":null;}public static String celebration(){return "salta,aplaude";}
 public static void main(String[] args)throws Exception{check(ProjectReplacementSpec.curve("return -96f*t*(1f-t);",true).root.at(.5f)==-24,"raw validated jump");check(ProjectReplacementSpec.curve("return (float)(24*Math.sin(t*Math.PI*2));",false).root.at(.25f)>23.99,"signed sway preserved");for(String bad:new String[]{"return 20*t;","return -200*t*(1-t);","return System.currentTimeMillis();","while(true){} return 0;","return -t;","return t/(t-.5);","return 0; System.exit(0);"}){try{ProjectReplacementSpec.curve(bad,true);throw new AssertionError("accepted "+bad);}catch(IllegalArgumentException expected){}}
 SceneDraft d=ScenePlanner.plan("un zorro salta",null,true).commit;Scene scene=new Scene(d);String actor=d.cast.get(0).name;float before=scene.pose(actor,.5f,null)[1];ProjectRuntime.Snapshot next=new ProjectRuntime.Snapshot();next.jump=Stage51ReplacementCheck.class.getMethod("jump",float.class);next.sway=Stage51ReplacementCheck.class.getMethod("sway",float.class);next.chat=Stage51ReplacementCheck.class.getMethod("reply",String.class);next.celebration=Stage51ReplacementCheck.class.getMethod("celebration");ProjectRuntime.active=next;check(Math.abs(scene.pose(actor,.5f,null)[1]-before+12)<.001,"actual renderer pose switched");check(ChatLanguage.socialReply("taller banana").equals("Motor nuevo"),"actual chat dispatched");check(ChatLanguage.socialReply("hola")==null,"null return belongs to replacement");check(ProjectRuntime.recipe("baila").equals("salta,aplaude"),"action recipe dispatched");CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();ProjectRuntime.prefs(c).edit().putString("active","{}").commit();c.fail=true;try{ProjectRuntime.commit(c,new JSONObject(),new ProjectRuntime.Snapshot(),new JSONArray());throw new AssertionError("failed persistence activated candidate");}catch(java.io.IOException expected){}check(ProjectRuntime.active==next,"commit failure preserves live snapshot");ProjectRuntime.active=new ProjectRuntime.Snapshot();check(Math.abs(scene.pose(actor,.5f,null)[1]-before)<.001,"fallback restored");System.out.println("PASS Stage51 bounded extraction, raw range and endpoint guards, signed sway, actual scene/chat/action dispatch and fallback");}
}
